package com.retailflow.pos.purchaseorder;
import com.retailflow.pos.common.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/purchase-orders") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") public class PurchaseOrderController{
 private final PurchaseOrderService s;public PurchaseOrderController(PurchaseOrderService s){this.s=s;}@GetMapping public ApiResponse<?>list(@RequestParam(required=false)PurchaseOrder.Status status){return ApiResponse.ok(s.list(status));}@GetMapping("/{id}")public ApiResponse<?>get(@PathVariable String id){return ApiResponse.ok(s.get(id));}@PostMapping public ApiResponse<?>create(@RequestBody PurchaseOrder v){return ApiResponse.ok(s.save(v));}@PutMapping("/{id}")public ApiResponse<?>update(@PathVariable String id,@RequestBody PurchaseOrder v){v.setId(id);return ApiResponse.ok(s.save(v));}@PostMapping("/{id}/send")public ApiResponse<?>send(@PathVariable String id){return ApiResponse.ok(s.transition(id,PurchaseOrder.Status.SENT));}@PostMapping("/{id}/cancel")public ApiResponse<?>cancel(@PathVariable String id){return ApiResponse.ok(s.transition(id,PurchaseOrder.Status.CANCELLED));}@PostMapping("/{id}/create-bill")public ApiResponse<?>bill(@PathVariable String id){return ApiResponse.ok(s.createBill(id));}
}
